// План specs/multi-business.md 1.3 (кейс MB-03). Диспетчер (Admin-dispatcher только в «test»). @prod-safe: только просмотр.
// В конце теста selected-company-id возвращается на «test».
import { test, expect } from '../../fixtures';
import { ONSITE_COMPANY, TEST_COMPANY, companyOption, companyOptions, expectSelected, openSwitcher, restoreTest, startInTest } from './business-helpers';

test.describe('Multi-business: dispatcher sees only own business (#04d339)', () => {
  test('Dispatcher of test: switcher shows only test, Onsite Locksmith is not offered #04d339 @desktop @prod-safe', async ({ asUser }) => {
    const dispatcher = await asUser('dispatcher');
    await startInTest(dispatcher);
    try {
      await dispatcher.goto('/dashboard');
      await expectSelected(dispatcher, TEST_COMPANY.name);

      // Источник: AC «מנהל עסק א' חסום מעסק ב'».
      await openSwitcher(dispatcher);
      await expect(companyOption(dispatcher, TEST_COMPANY.name)).toBeVisible();
      await expect(companyOptions(dispatcher)).toHaveCount(1);
      await expect(dispatcher.getByText(ONSITE_COMPANY.name)).toHaveCount(0);
      await dispatcher.keyboard.press('Escape');
    } finally {
      await restoreTest(dispatcher);
    }
  });
});
